## 完成回调 (Completion Handler)

iOS 17+ 的 `withAnimation` 支持完成回调：

```swift
struct CompletionDemo: View {
    @State private var phase = 0
    @State private var statusText = "就绪"

    var body: some View {
        VStack(spacing: 24) {
            Circle()
                .frame(width: 60, height: 60)
                .foregroundStyle(phaseColor)
                .scaleEffect(phase >= 1 ? 1.2 : 1.0)
                .offset(y: phase >= 2 ? -50 : 0)
                .rotationEffect(.degrees(phase >= 3 ? 360 : 0))

            Text(statusText)
                .font(.headline)
                .foregroundStyle(.secondary)

            Button("开始序列动画") {
                startSequence()
            }
            .disabled(phase > 0)
        }
    }

    var phaseColor: Color {
        switch phase {
        case 0: return .blue
        case 1: return .green
        case 2: return .orange
        default: return .red
        }
    }

    func startSequence() {
        statusText = "阶段 1: 放大"
        withAnimation(.easeOut(duration: 0.5)) {
            phase = 1
        } completion: {
            statusText = "阶段 2: 上移"
            withAnimation(.spring(response: 0.4)) {
                phase = 2
            } completion: {
                statusText = "阶段 3: 旋转"
                withAnimation(.easeInOut(duration: 0.8)) {
                    phase = 3
                } completion: {
                    statusText = "完成！"
                }
            }
        }
    }
}
```

```mermaid
sequenceDiagram
    participant U as 用户
    participant A as withAnimation
    participant V as 视图

    U->>A: 触发阶段 1
    A->>V: 放大动画 0.5s
    V-->>A: completion 回调
    A->>V: 上移动画 (spring)
    V-->>A: completion 回调
    A->>V: 旋转动画 0.8s
    V-->>A: completion 回调
    Note over V: 序列动画完成
```

